L000017	\title{Representability for Quantum Theory beyond Particle-Number Conservation}
L000018	
L000019	\author{David A. Mazziotti}
L000020	
L000021	\email{damazz@uchicago.edu}
L000022	\affiliation{Department of Chemistry and The James Franck Institute, The University of Chicago, Chicago, IL 60637}
L000023	
L000024	\date{Submitted December 10, 2025\textcolor{black}{; Revised February 2, 2026}}
L000025	
